#include "util.h"

/* Everything a pinned LC_ALL was covering besides the charset. Clearing it is what lets LC_CTYPE
 * apply at all, so each category is restated at the value it had: hax is entitled to the encoding
 * its own text is in, not to the user's collation, messages or number format. */
static const char *const PINNED_CATEGORIES[] = {
    "LC_COLLATE", "LC_MONETARY", "LC_NUMERIC", "LC_TIME", "LC_MESSAGES",
};

char *spawn_shell_cmd_force_utf8(char *shell_cmd)
{
    const char *ctype = shell_cmd ? locale_child_ctype_override() : NULL;
    if (!ctype)
        return shell_cmd;

    struct buf command;
    buf_init(&command);
    buf_append_str(&command, "export");

    const char *pinned = getenv("LC_ALL");
    char *quoted_pinned = pinned && *pinned ? shell_single_quote(pinned) : NULL;
    for (size_t i = 0; quoted_pinned && i < sizeof(PINNED_CATEGORIES) / sizeof(*PINNED_CATEGORIES);
         i++) {
        char *assignment = xasprintf(" %s=%s", PINNED_CATEGORIES[i], quoted_pinned);
        buf_append_str(&command, assignment);
        free(assignment);
    }
    free(quoted_pinned);

    /* An assignment prefix would only reach a simple command, and `sh` rejects one before the
     * `{ ...; }` a caller may well pass. Exporting first reaches any command shape. setlocale()
     * ignores an empty LC_ALL, which the pinned one would otherwise outrank. */
    char *quoted_ctype = shell_single_quote(ctype);
    char *tail = xasprintf(" LC_ALL= LC_CTYPE=%s; %s", quoted_ctype, shell_cmd);
    buf_append_str(&command, tail);
    free(tail);
    free(quoted_ctype);
    free(shell_cmd);
    return buf_steal(&command);
}

void spawn_parent_ignore_signals(struct spawn_signal_state *state)
{
    struct sigaction ignored;
    memset(&ignored, 0, sizeof(ignored));
    ignored.sa_handler = SIG_IGN;
    sigemptyset(&ignored.sa_mask);
    sigaction(SIGINT, &ignored, &state->sigint);
    sigaction(SIGQUIT, &ignored, &state->sigquit);
    sigaction(SIGPIPE, &ignored, &state->sigpipe);
}

void spawn_parent_restore_signals(const struct spawn_signal_state *state)
{
    sigaction(SIGINT, &state->sigint, NULL);
    sigaction(SIGQUIT, &state->sigquit, NULL);
    sigaction(SIGPIPE, &state->sigpipe, NULL);
}

void spawn_child_reset_signals(void)
{
    /* signal() is async-signal-safe and avoids constructing sigaction state after fork. */
    signal(SIGINT, SIG_DFL);
    signal(SIGQUIT, SIG_DFL);
    signal(SIGPIPE, SIG_DFL);
}

void spawn_child_redirect_stdio_to_null(void)
{
    int null_fd = open("/dev/null", O_RDWR);
    if (null_fd < 0)
        return;
    dup2(null_fd, STDIN_FILENO);
    dup2(null_fd, STDOUT_FILENO);
    dup2(null_fd, STDERR_FILENO);
    if (null_fd > STDERR_FILENO)
        close(null_fd);
}

void spawn_child_die_with_parent(pid_t parent_pid, int signal_number)
{
#ifdef __linux__
    prctl(PR_SET_PDEATHSIG, signal_number);
    /* PR_SET_PDEATHSIG does not report a parent death that precedes the prctl call. */
    if (getppid() != parent_pid)
        _exit(0);
#else
    (void)parent_pid;
    (void)signal_number;
#endif
}

int spawn_wait_child(pid_t pid)
{
    int status;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno != EINTR)
            return -1;
    }
    return status;
}

int spawn_reap_if_exited(pid_t pid)
{
    int status;
    pid_t waited_pid = waitpid(pid, &status, WNOHANG);
    return waited_pid == pid || (waited_pid < 0 && errno == ECHILD);
}

static void exec_shell(const char *shell_cmd)
{
    char *const argv[] = {(char *)"sh", (char *)"-c", (char *)shell_cmd, NULL};
    execv("/bin/sh", argv);
}

int spawn_shell_wait(const char *shell_cmd)
{
    if (!shell_cmd) {
        errno = EINVAL;
        return -1;
    }

    struct spawn_signal_state signals;
    spawn_parent_ignore_signals(&signals);

    pid_t pid = fork();
    if (pid < 0) {
        int saved_errno = errno;
        spawn_parent_restore_signals(&signals);
        errno = saved_errno;
        return -1;
    }
    if (pid == 0) {
        spawn_child_reset_signals();
        exec_shell(shell_cmd);
        _exit(127);
    }

    int status = spawn_wait_child(pid);
    spawn_parent_restore_signals(&signals);
    return status;
}

enum spawn_pipe_mode {
    SPAWN_PIPE_READ,
    SPAWN_PIPE_WRITE,
};

static int spawn_pipe_open_mode(struct spawn_pipe *result, const char *shell_cmd,
                                enum spawn_pipe_mode mode)
{
    if (!result || !shell_cmd) {
        if (result)
            memset(result, 0, sizeof(*result));
        errno = EINVAL;
        return -1;
    }
    memset(result, 0, sizeof(*result));

    int pipe_fds[2];
    if (pipe(pipe_fds) < 0)
        return -1;

    int child_fd = mode == SPAWN_PIPE_READ ? pipe_fds[1] : pipe_fds[0];
    int child_target = mode == SPAWN_PIPE_READ ? STDOUT_FILENO : STDIN_FILENO;
    int parent_fd = mode == SPAWN_PIPE_READ ? pipe_fds[0] : pipe_fds[1];

    spawn_parent_ignore_signals(&result->parent_signals);

    pid_t pid = fork();
    if (pid < 0) {
        int saved_errno = errno;
        spawn_parent_restore_signals(&result->parent_signals);
        close(pipe_fds[0]);
        close(pipe_fds[1]);
        memset(result, 0, sizeof(*result));
        errno = saved_errno;
        return -1;
    }
    if (pid == 0) {
        spawn_child_reset_signals();
        /* Closing this first handles a parent fd that reused the target standard descriptor. */
        close(parent_fd);
        if (child_fd != child_target) {
            if (dup2(child_fd, child_target) < 0)
                _exit(127);
            close(child_fd);
        }
        exec_shell(shell_cmd);
        _exit(127);
    }

    close(child_fd);
    FILE *stream = fdopen(parent_fd, mode == SPAWN_PIPE_READ ? "r" : "w");
    if (!stream) {
        int saved_errno = errno;
        close(parent_fd);
        /* A child reading /dev/tty may not notice that its pipe end closed. */
        kill(pid, SIGTERM);
        (void)spawn_wait_child(pid);
        spawn_parent_restore_signals(&result->parent_signals);
        memset(result, 0, sizeof(*result));
        errno = saved_errno;
        return -1;
    }

    result->stream = stream;
    result->pid = pid;
    return 0;
}

int spawn_pipe_open_write(struct spawn_pipe *pipe, const char *shell_cmd)
{
    return spawn_pipe_open_mode(pipe, shell_cmd, SPAWN_PIPE_WRITE);
}

int spawn_pipe_open_read(struct spawn_pipe *pipe, const char *shell_cmd)
{
    return spawn_pipe_open_mode(pipe, shell_cmd, SPAWN_PIPE_READ);
}

int spawn_pipe_close(struct spawn_pipe *pipe)
{
    if (!pipe || !pipe->stream)
        return 0;

    /* Closing first delivers EOF to a reader or SIGPIPE to a writer before waitpid. */
    fclose(pipe->stream);
    pipe->stream = NULL;
    int status = spawn_wait_child(pipe->pid);
    spawn_parent_restore_signals(&pipe->parent_signals);
    pipe->pid = 0;
    return status;
}

/* EOF does not imply child exit, so retain the capture deadline while reaping. */
static int wait_child_until(pid_t pid, long deadline_ms)
{
    const struct timespec poll_interval = {.tv_nsec = 5 * 1000000};

    for (;;) {
        int status;
        pid_t waited_pid = waitpid(pid, &status, WNOHANG);
        if (waited_pid == pid)
            return status;
        if (waited_pid < 0 && errno != EINTR)
            return -1;
        if (monotonic_ms() >= deadline_ms) {
            kill(pid, SIGKILL);
            return spawn_wait_child(pid);
        }
        nanosleep(&poll_interval, NULL);
    }
}

int spawn_wait_child_timeout(pid_t pid, int timeout_ms)
{
    return wait_child_until(pid, monotonic_ms() + timeout_ms);
}

char *spawn_capture_stdout(const char *const *argv, size_t max_bytes, int timeout_ms,
                           size_t *out_len)
{
    if (!argv || !argv[0] || !out_len || timeout_ms <= 0) {
        errno = EINVAL;
        return NULL;
    }

    int pipe_fds[2];
    if (pipe(pipe_fds) < 0)
        return NULL;

    struct spawn_signal_state signals;
    spawn_parent_ignore_signals(&signals);

    pid_t pid = fork();
    if (pid < 0) {
        int saved_errno = errno;
        close(pipe_fds[0]);
        close(pipe_fds[1]);
        spawn_parent_restore_signals(&signals);
        errno = saved_errno;
        return NULL;
    }
    if (pid == 0) {
        close(pipe_fds[0]);
        if (dup2(pipe_fds[1], STDOUT_FILENO) < 0)
            _exit(127);
        if (pipe_fds[1] != STDOUT_FILENO)
            close(pipe_fds[1]);

        int null_fd = open("/dev/null", O_RDWR);
        if (null_fd >= 0) {
            dup2(null_fd, STDIN_FILENO);
            dup2(null_fd, STDERR_FILENO);
            if (null_fd > STDERR_FILENO)
                close(null_fd);
        }
        spawn_child_reset_signals();
        execvp(argv[0], (char *const *)argv);
        _exit(127);
    }
    close(pipe_fds[1]);

    long deadline_ms = monotonic_ms() + timeout_ms;
    struct buf output;
    buf_init(&output);
    int capture_failed = 0;
    char chunk[65536];
    for (;;) {
        long remaining_ms = deadline_ms - monotonic_ms();
        if (remaining_ms <= 0) {
            capture_failed = 1;
            break;
        }

        struct pollfd poll_fd = {.fd = pipe_fds[0], .events = POLLIN};
        int poll_result = poll(&poll_fd, 1, remaining_ms > INT_MAX ? INT_MAX : (int)remaining_ms);
        if (poll_result < 0 && errno == EINTR)
            continue;
        if (poll_result <= 0) {
            capture_failed = 1;
            break;
        }

        ssize_t bytes_read = read(pipe_fds[0], chunk, sizeof(chunk));
        if (bytes_read < 0 && errno == EINTR)
            continue;
        if (bytes_read < 0) {
            capture_failed = 1;
            break;
        }
        if (bytes_read == 0)
            break;
        if ((size_t)bytes_read > max_bytes - output.len) {
            capture_failed = 1;
            break;
        }
        buf_append(&output, chunk, (size_t)bytes_read);
    }
    close(pipe_fds[0]);

    int status;
    if (capture_failed) {
        kill(pid, SIGKILL);
        status = spawn_wait_child(pid);
    } else {
        status = wait_child_until(pid, deadline_ms);
    }
    spawn_parent_restore_signals(&signals);

    if (capture_failed || status < 0 || !WIFEXITED(status) || WEXITSTATUS(status) != 0 ||
        output.len == 0) {
        buf_free(&output);
        return NULL;
    }
    *out_len = output.len;
    return buf_steal(&output);
}

/* SPDX-License-Identifier: MIT */
#include "util.h"

#include <errno.h>
#include <fcntl.h>
#include <langinfo.h>
#include <limits.h>
#include <locale.h>
#include <stdarg.h>
#include <stdatomic.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/stat.h>

#include "terminal/ansi.h"
#include "terminal/theme.h"

static int locale_is_utf8;
static int locale_children_are_utf8;

void locale_init_utf8(void)
{
    locale_is_utf8 = 0;
    locale_children_are_utf8 = 0;

    setlocale(LC_CTYPE, "");
    if (strcmp(nl_langinfo(CODESET), "UTF-8") == 0) {
        locale_is_utf8 = 1;
        locale_children_are_utf8 = 1;
        return;
    }
    /* OpenBSD ships no default locale at all, yet renders UTF-8 whatever the locale claims. This
     * process needs one regardless of the environment: mbrtowc() decodes the model's text here, and
     * without it every multibyte character is measured as its separate bytes.
     *
     * The spellings are PEP 538's, there being no portable one: glibc and the BSDs answer to
     * C.UTF-8, macOS only to a bare UTF-8. A language-bearing name is the last resort, for systems
     * where only specific locales were generated. */
    static const char *const CANDIDATES[] = {"C.UTF-8", "C.utf8", "UTF-8", "en_US.UTF-8"};
    const char *chosen = NULL;
    for (size_t i = 0; !chosen && i < sizeof(CANDIDATES) / sizeof(CANDIDATES[0]); i++)
        chosen = setlocale(LC_CTYPE, CANDIDATES[i]);
    if (!chosen) {
        hax_warn("no UTF-8 locale found; non-ASCII text will be misread and misaligned");
        return;
    }
    locale_is_utf8 = 1;

    /* setlocale() reaches this process alone, so children need the choice published. A non-UTF-8
     * LC_ALL outranks LC_CTYPE and would mask it, and clearing it would move every other category
     * with it — leave the pinned locale alone and let callers render ASCII for children instead. */
    const char *lc_all = getenv("LC_ALL");
    if (lc_all && *lc_all)
        return;
    setenv("LC_CTYPE", chosen, 1);
    locale_children_are_utf8 = 1;
}

int locale_have_utf8(void)
{
    return locale_is_utf8;
}

const char *locale_child_ctype_override(void)
{
    if (locale_children_are_utf8 || !locale_is_utf8)
        return NULL;
    return setlocale(LC_CTYPE, NULL);
}

static void die_oom(void)
{
    fprintf(stderr, "hax: out of memory\n");
    abort();
}

/* Lets stdout presentation detect diagnostics emitted directly by lower layers. */
static _Atomic unsigned long diagnostic_sequence;

unsigned long hax_diag_sequence(void)
{
    return atomic_load_explicit(&diagnostic_sequence, memory_order_relaxed);
}

static void emit_diagnostic(const char *color, const char *format, va_list args)
{
    int styled = isatty(fileno(stderr)) && *color;
    if (styled)
        fputs(color, stderr);
    fputs("hax: ", stderr);
    vfprintf(stderr, format, args);
    if (styled)
        fputs(ANSI_RESET, stderr);
    fputc('\n', stderr);
    fflush(stderr);
    atomic_fetch_add_explicit(&diagnostic_sequence, 1, memory_order_relaxed);
}

void hax_err(const char *format, ...)
{
    va_list args;
    va_start(args, format);
    emit_diagnostic(theme_open(THEME_ERROR), format, args);
    va_end(args);
}

void hax_warn(const char *format, ...)
{
    va_list args;
    va_start(args, format);
    emit_diagnostic(theme_open(THEME_WARN), format, args);
    va_end(args);
}

void *xmalloc(size_t size)
{
    void *result = malloc(size ? size : 1);
    if (!result)
        die_oom();
    return result;
}

void *xcalloc(size_t count, size_t element_size)
{
    void *result = (count && element_size) ? calloc(count, element_size) : calloc(1, 1);
    if (!result)
        die_oom();
    return result;
}

void *xrealloc(void *ptr, size_t size)
{
    void *result = realloc(ptr, size ? size : 1);
    if (!result)
        die_oom();
    return result;
}

char *xstrdup(const char *str)
{
    if (!str)
        return NULL;
    char *result = strdup(str);
    if (!result)
        die_oom();
    return result;
}

void string_array_free(char **strings)
{
    if (!strings)
        return;
    for (char **string = strings; *string; string++)
        free(*string);
    free(strings);
}

char *xvasprintf(const char *format, va_list args)
{
    va_list copy;
    va_copy(copy, args);
    int length = vsnprintf(NULL, 0, format, copy);
    va_end(copy);
    if (length < 0)
        return NULL;

    char *result = xmalloc((size_t)length + 1);
    va_copy(copy, args);
    int written = vsnprintf(result, (size_t)length + 1, format, copy);
    va_end(copy);
    if (written < 0 || written > length) {
        free(result);
        return NULL;
    }
    return result;
}

char *xasprintf(const char *format, ...)
{
    va_list args;
    va_start(args, format);
    char *result = xvasprintf(format, args);
    va_end(args);
    return result;
}

char *shell_single_quote(const char *str)
{
    struct buf quoted;
    buf_init(&quoted);
    buf_append(&quoted, "'", 1);
    for (; str && *str; str++) {
        if (*str == '\'')
            buf_append_str(&quoted, "'\\''");
        else
            buf_append(&quoted, str, 1);
    }
    buf_append(&quoted, "'", 1);
    return buf_steal(&quoted);
}

void gen_uuid_v4(char out[37])
{
    uint8_t bytes[16];
    int fd = open("/dev/urandom", O_RDONLY | O_CLOEXEC);
    if (fd < 0) {
        hax_err("open /dev/urandom: %s", strerror(errno));
        abort();
    }

    size_t bytes_read = 0;
    while (bytes_read < sizeof(bytes)) {
        ssize_t count = read(fd, bytes + bytes_read, sizeof(bytes) - bytes_read);
        if (count < 0) {
            if (errno == EINTR)
                continue;
            hax_err("read /dev/urandom: %s", strerror(errno));
            abort();
        }
        if (count == 0) {
            hax_err("unexpected EOF on /dev/urandom");
            abort();
        }
        bytes_read += (size_t)count;
    }
    close(fd);

    bytes[6] = (bytes[6] & 0x0f) | 0x40; /* RFC 4122 version 4 */
    bytes[8] = (bytes[8] & 0x3f) | 0x80; /* RFC 4122 variant */

    snprintf(out, 37, "%02x%02x%02x%02x-%02x%02x-%02x%02x-%02x%02x-%02x%02x%02x%02x%02x%02x",
             bytes[0], bytes[1], bytes[2], bytes[3], bytes[4], bytes[5], bytes[6], bytes[7],
             bytes[8], bytes[9], bytes[10], bytes[11], bytes[12], bytes[13], bytes[14], bytes[15]);
}

int parse_int(const char *str, int *out)
{
    if (!str || !*str)
        return 0;

    char *end;
    errno = 0;
    long value = strtol(str, &end, 10);
    if (end == str || *end != '\0')
        return 0;
    if (errno == ERANGE || value > INT_MAX || value < INT_MIN)
        return 0;
    *out = (int)value;
    return 1;
}

int write_all(int fd, const void *data, size_t length)
{
    const char *cursor = data;
    while (length > 0) {
        size_t request = length > (size_t)SSIZE_MAX ? (size_t)SSIZE_MAX : length;
        ssize_t written = write(fd, cursor, request);
        if (written < 0) {
            if (errno == EINTR)
                continue;
            return -1;
        }
        if (written == 0) {
            errno = EIO;
            return -1;
        }
        cursor += written;
        length -= (size_t)written;
    }
    return 0;
}

static int regular_mode_or_error(mode_t mode)
{
    if (S_ISREG(mode))
        return 0;
    errno = S_ISDIR(mode) ? EISDIR : EINVAL;
    return -1;
}

int ensure_regular_file(const char *path)
{
    struct stat status;
    if (stat(path, &status) < 0)
        return -1;
    return regular_mode_or_error(status.st_mode);
}

int open_regular_file(const char *path)
{
    int fd = open(path, O_RDONLY | O_CLOEXEC | O_NONBLOCK);
    if (fd < 0)
        return -1;

    struct stat status;
    if (fstat(fd, &status) == 0 && regular_mode_or_error(status.st_mode) == 0)
        return fd;

    int saved_errno = errno;
    close(fd);
    errno = saved_errno;
    return -1;
}

static ssize_t read_retry(int fd, void *data, size_t length)
{
    ssize_t bytes_read;
    do {
        bytes_read = read(fd, data, length);
    } while (bytes_read < 0 && errno == EINTR);
    return bytes_read;
}

char *slurp_file(const char *path, size_t *out_len)
{
    int saved_errno;
    int fd = open_regular_file(path);
    if (fd < 0)
        return NULL;

    struct buf contents;
    buf_init(&contents);
    char chunk[8192];
    for (;;) {
        ssize_t bytes_read = read_retry(fd, chunk, sizeof(chunk));
        if (bytes_read < 0)
            goto error;
        if (bytes_read == 0)
            break;
        buf_append(&contents, chunk, (size_t)bytes_read);
    }

    close(fd);
    if (out_len)
        *out_len = contents.len;
    return buf_steal(&contents);

error:
    saved_errno = errno;
    buf_free(&contents);
    close(fd);
    errno = saved_errno;
    return NULL;
}

char *slurp_file_capped(const char *path, size_t cap, size_t *out_len, int *out_truncated)
{
    int saved_errno;
    int truncated = 0;
    int fd = open_regular_file(path);
    if (fd < 0)
        return NULL;

    struct buf contents;
    buf_init(&contents);
    char chunk[8192];
    while (contents.len < cap) {
        size_t remaining = cap - contents.len;
        size_t request = remaining < sizeof(chunk) ? remaining : sizeof(chunk);
        ssize_t bytes_read = read_retry(fd, chunk, request);
        if (bytes_read < 0)
            goto error;
        if (bytes_read == 0)
            break;
        buf_append(&contents, chunk, (size_t)bytes_read);
    }

    if (contents.len == cap) {
        char extra;
        ssize_t bytes_read = read_retry(fd, &extra, 1);
        if (bytes_read < 0)
            goto error;
        truncated = bytes_read > 0;
    }

    close(fd);
    if (out_len)
        *out_len = contents.len;
    if (out_truncated)
        *out_truncated = truncated;
    return buf_steal(&contents);

error:
    saved_errno = errno;
    buf_free(&contents);
    close(fd);
    errno = saved_errno;
    return NULL;
}

static char *xdg_hax_path(const char *env_name, const char *home_relative,
                          const char *relative_path)
{
    const char *xdg_base = getenv(env_name);
    if (xdg_base && *xdg_base)
        return xasprintf("%s/hax/%s", xdg_base, relative_path);
    const char *home = getenv("HOME");
    if (home && *home)
        return xasprintf("%s/%s/hax/%s", home, home_relative, relative_path);
    return NULL;
}

char *xdg_hax_config_path(const char *relative_path)
{
    return xdg_hax_path("XDG_CONFIG_HOME", ".config", relative_path);
}

char *xdg_hax_state_path(const char *relative_path)
{
    return xdg_hax_path("XDG_STATE_HOME", ".local/state", relative_path);
}

char *xdg_hax_cache_path(const char *relative_path)
{
    return xdg_hax_path("XDG_CACHE_HOME", ".cache", relative_path);
}

char *dup_trim_trailing_slash(const char *str)
{
    size_t length = strlen(str);
