long parse_size(const char *str)
{
    if (!str || !*str)
        return 0;

    char *end;
    errno = 0;
    long value = strtol(str, &end, 10);
    if (end == str || value <= 0 || errno == ERANGE)
        return 0;
    while (*end == ' ' || *end == '\t')
        end++;

    long multiplier = 1;
    switch (*end) {
    case 'k':
    case 'K':
        multiplier = 1024L;
        end++;
        break;
    case 'm':
    case 'M':
        multiplier = 1024L * 1024L;
        end++;
        break;
    }
    while (*end == ' ' || *end == '\t')
        end++;
    if (*end != '\0' || value > LONG_MAX / multiplier)
        return 0;
    return value * multiplier;
}

long parse_duration_ms(const char *str)
{
    if (!str || !*str)
        return -1;

    char *end;
    errno = 0;
    long value = strtol(str, &end, 10);
    if (end == str || value < 0 || errno == ERANGE)
        return -1;
    while (*end == ' ' || *end == '\t')
        end++;

    long multiplier;
    /* Match "ms" before "m". */
    if ((end[0] == 'm' || end[0] == 'M') && (end[1] == 's' || end[1] == 'S')) {
        multiplier = 1;
        end += 2;
    } else if (*end == '\0' || *end == 's' || *end == 'S') {
        multiplier = 1000;
        if (*end)
            end++;
    } else if (*end == 'm' || *end == 'M') {
        multiplier = 60000;
        end++;
    } else if (*end == 'h' || *end == 'H') {
        multiplier = 3600000;
        end++;
    } else {
        return -1;
    }
    while (*end == ' ' || *end == '\t')
        end++;
    if (*end != '\0' || (multiplier > 1 && value > LONG_MAX / multiplier))
        return -1;
    return value * multiplier;
}

long monotonic_ms(void)
{
